#!/usr/bin/env python3
"""Creator OS Build 03 — clean standalone local server.
Research vault + provenance-first Narrative Intelligence Engine.
No third-party Python packages required.
"""
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from urllib.parse import urlparse,parse_qs
import json,sqlite3,os,datetime,html
from research_engine import discover,fetch_page,extract_claim_candidates,research_contract
from narrative_engine import build_narrative
ROOT=os.path.dirname(os.path.abspath(__file__));DB=os.path.join(ROOT,'creator_os_build03.db');PORT=int(os.getenv('PORT','8787'))
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def db():
 c=sqlite3.connect(DB);c.row_factory=sqlite3.Row;c.executescript('''CREATE TABLE IF NOT EXISTS channels(id TEXT PRIMARY KEY,name TEXT,kind TEXT,language TEXT,cadence TEXT,color TEXT);CREATE TABLE IF NOT EXISTS topics(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,angle TEXT,score INTEGER,demand INTEGER,competition INTEGER,originality INTEGER,researchability INTEGER,status TEXT,created_at TEXT);CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,channel_id TEXT,kind TEXT,status TEXT,stage TEXT,progress INTEGER,updated_at TEXT,error TEXT);CREATE TABLE IF NOT EXISTS sources(id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER,url TEXT,title TEXT,source_type TEXT,trust INTEGER,notes TEXT);CREATE TABLE IF NOT EXISTS claims(id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER,claim TEXT,source_id INTEGER,confidence INTEGER,status TEXT,conflict TEXT,notes TEXT);CREATE TABLE IF NOT EXISTS discoveries(id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER,query TEXT,payload TEXT,created_at TEXT);CREATE TABLE IF NOT EXISTS narrative_packages(id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER,payload TEXT,created_at TEXT,version INTEGER);''')
 if c.execute('SELECT COUNT(*) n FROM channels').fetchone()['n']==0:c.executemany('INSERT INTO channels VALUES(?,?,?,?,?,?)',[('bgmi','BGMI Live','gaming','Hindi','3 lives / week','#f59e0b'),('kids','Hindi Kids Stories','kids','Hindi','5 videos / week','#22c55e'),('history','Itihas Uncovered','documentary','Hindi','2 documentaries / week','#a78bfa'),('tech','Tech Explained Hindi','tech','Hindi','2 videos / week','#38bdf8'),('blog','Research Desk','blog','Hindi + English','Daily','#fb7185')])
 if c.execute('SELECT COUNT(*) n FROM topics').fetchone()['n']==0:c.executemany('INSERT INTO topics(title,angle,score,demand,competition,originality,researchability,status,created_at) VALUES(?,?,?,?,?,?,?,?,?)',[('Battle of Panipat','The logistics, alliances and decisions that shaped the outcome before the main clash',92,91,76,94,97,'approved',now()),('Nalanda: What Actually Happened?','Separate the popular destruction narrative from what primary and scholarly sources support',89,88,82,91,95,'candidate',now()),('How UPI Became India’s Invisible Infrastructure','The technical and economic story behind India’s real-time payments scale',87,86,71,88,96,'candidate',now())])
 c.commit();return c
def rows(c,q,a=()):return [dict(x) for x in c.execute(q,a).fetchall()]
def body(h):
 try:return json.loads(h.rfile.read(int(h.headers.get('Content-Length','0') or 0)) or '{}')
 except:return {}
HTML='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Creator OS Build 03</title><style>:root{--bg:#07090d;--p:#0d1118;--p2:#111722;--line:#202938;--text:#f4f7fb;--muted:#8996a8;--a:#8b5cf6;--good:#34d399;--warn:#fbbf24}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,sans-serif}.app{display:flex;min-height:100vh}.side{width:235px;position:fixed;inset:0 auto 0 0;background:#090c12;border-right:1px solid var(--line);padding:18px 14px}.brand{font-size:19px;font-weight:800;padding:12px}.brand b{color:#b99cff}.nav{margin-top:18px}.nav button{width:100%;border:0;background:none;color:#9aa6b8;text-align:left;padding:11px 12px;border-radius:10px;cursor:pointer}.nav button:hover,.nav button.active{background:#ffffff08;color:#fff}.main{margin-left:235px;padding:30px;max-width:1500px;flex:1}.eyebrow,.mini{font-size:11px;color:var(--muted)}.eyebrow{text-transform:uppercase;letter-spacing:.16em}h1{font-size:32px;margin:8px 0 5px}h2{font-size:18px}.muted{color:var(--muted)}.grid{display:grid;gap:14px}.metrics{grid-template-columns:repeat(4,1fr);margin-top:25px}.split{grid-template-columns:1fr 1fr}.panel,.card,.job,.topic{background:var(--p);border:1px solid var(--line);border-radius:16px;padding:17px}.job,.topic{background:var(--p2)}.list{display:grid;gap:8px;margin-top:12px}.row{display:flex;align-items:center;gap:12px}.between{justify-content:space-between}.metric .v{font-size:28px;font-weight:750;margin-top:7px}.btn{border:1px solid var(--line);background:#111722;color:#fff;border-radius:10px;padding:9px 13px;cursor:pointer}.primary{background:var(--a);border-color:var(--a)}.badge{font-size:11px;border:1px solid var(--line);border-radius:999px;padding:4px 8px;color:#aab4c4}.good{color:var(--good)}.warn{color:var(--warn)}input{width:100%;background:#080b10;color:#fff;border:1px solid var(--line);border-radius:10px;padding:11px;outline:0}.bar{height:5px;background:#ffffff09;border-radius:9px;overflow:hidden}.bar i{display:block;height:100%;background:var(--a)}.hidden{display:none}.result{white-space:pre-wrap;max-height:520px;overflow:auto;background:#080b10;border:1px solid var(--line);border-radius:10px;padding:12px;font:12px ui-monospace,monospace;color:#b9c3d0}.score{font-size:21px;color:#b99cff;font-weight:700}@media(max-width:800px){.side{display:none}.main{margin-left:0;padding:18px}.metrics,.split{grid-template-columns:1fr 1fr}}@media(max-width:560px){.metrics,.split{grid-template-columns:1fr}}</style></head><body><div class="app"><aside class="side"><div class="brand">Creator<b>OS</b><div class="mini">Build 03 · Narrative Intelligence</div></div><div class="nav"><button class="active" onclick="show('home',this)">◈ Command</button><button onclick="show('studio',this)">✦ Narrative Studio</button><button onclick="show('research',this)">▤ Research Vault</button><button onclick="show('topics',this)">⌁ Topic Lab</button></div></aside><main class="main"><section id="home"><div class="row between"><div><div class="eyebrow">clean build</div><h1>Evidence → story → derivatives.</h1><div class="muted">Build 03 turns the research vault into a provenance-first narrative package.</div></div><button class="btn primary" onclick="show('studio')">＋ Build narrative</button></div><div class="grid metrics"><div class="panel metric"><div class="eyebrow">Sources</div><div class="v" id="sm">—</div><div class="mini">local evidence</div></div><div class="panel metric"><div class="eyebrow">Claims</div><div class="v" id="cm">—</div><div class="mini">review state preserved</div></div><div class="panel metric"><div class="eyebrow">Narratives</div><div class="v" id="nm">—</div><div class="mini">versioned packages</div></div><div class="panel metric"><div class="eyebrow">Publish gate</div><div class="v">ON</div><div class="mini">human approval required</div></div></div><div class="grid split" style="margin-top:14px"><div class="panel"><h2>Pipeline</h2><div class="list"><div class="job">01 · demand signal</div><div class="job">02 · source graph</div><div class="job">03 · claim matrix</div><div class="job">04 · contradictions</div><div class="job">05 · thesis + hooks</div><div class="job">06 · shot / thumbnail / Shorts / blog</div></div></div><div class="panel"><h2>Rules</h2><div class="list"><div class="job"><span class="good">●</span> competitor content is a signal, never a script source</div><div class="job"><span class="good">●</span> factual claims keep provenance</div><div class="job"><span class="good">●</span> unresolved claims remain visible</div><div class="job"><span class="good">●</span> publishing stays human-gated</div></div></div></div></section><section id="studio" class="hidden"><div class="eyebrow">Narrative studio</div><h1>Build the story architecture</h1><div class="muted">No generic script dump. The output is a structured production package.</div><div class="panel" style="margin-top:22px"><div class="row"><input id="topic" value="Battle of Panipat"><button class="btn primary" onclick="build()">Build</button></div><div id="out" style="margin-top:15px"></div></div></section><section id="research" class="hidden"><div class="eyebrow">Research vault</div><h1>Evidence before narration</h1><div class="panel" style="margin-top:22px"><div class="row"><input id="q" value="Battle of Panipat"><button class="btn primary" onclick="disc()">Discover</button></div><div id="results" class="list"></div></div><div class="panel" style="margin-top:14px"><div class="row"><input id="url" placeholder="Authoritative source URL"><button class="btn" onclick="ingest()">Ingest</button></div><div id="ing" class="mini" style="margin-top:10px"></div></div></section><section id="topics" class="hidden"><div class="eyebrow">Topic lab</div><h1>Demand without cloning</h1><div id="topicList" class="grid split" style="margin-top:18px"></div></section></main></div><script>const ids=['home','studio','research','topics'];let tid=0;function show(id,b){ids.forEach(x=>document.getElementById(x).classList.toggle('hidden',x!==id));document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));if(b)b.classList.add('active');if(id==='topics')topics()}async function j(u,o){return (await fetch(u,o)).json()}function e(x){return String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}async function topics(){let d=await j('/api/topics');document.getElementById('topicList').innerHTML=d.topics.map(x=>`<div class="topic"><div class="row between"><div><b>${e(x.title)}</b><div class="mini">${e(x.angle)}</div></div><div class="score">${x.score}</div></div><div class="list"><div class="mini">Demand ${x.demand} · Originality ${x.originality} · Research ${x.researchability}</div><button class="btn" onclick="tid=${x.id};document.getElementById('topic').value='${e(x.title).replaceAll("'","\\'")}';show('studio')">Build narrative</button></div></div>`).join('')}async function build(){let topic=document.getElementById('topic').value.trim();let d=await j('/api/narrative/build',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic,topic_id:tid})});tid=d.topic_id;let p=d.package;document.getElementById('out').innerHTML=`<div class="grid split"><div class="card"><div class="eyebrow">Thesis</div><h2>${e(p.selected_angle.title)}</h2><p class="muted">${e(p.selected_angle.thesis)}</p></div><div class="card"><div class="eyebrow">Gates</div><div class="list">${Object.entries(p.quality_gates).map(([k,v])=>`<div class="row between"><span>${e(k)}</span><b class="${v?'good':'warn'}">${v?'PASS':'REVIEW'}</b></div>`).join('')}</div></div></div><div class="grid split" style="margin-top:14px"><div class="card"><div class="eyebrow">Narrative arc</div><div class="list">${p.outline.structure.map(x=>`<div class="job"><b>${e(x.beat)}</b><div class="mini">${e(x.purpose)} · ${x.duration_sec}s</div></div>`).join('')}</div></div><div class="card"><div class="eyebrow">Shot plan</div><div class="list">${p.shot_plan.map(x=>`<div class="job"><b>${x.shot}. ${e(x.role)}</b><div class="mini">${e(x.visual)} · ${e(x.provenance)}</div></div>`).join('')}</div></div></div><div class="panel" style="margin-top:14px"><div class="eyebrow">Derivatives</div><div class="list">${p.shorts_candidates.map(x=>`<div class="job"><b>${e(x.title)}</b><div class="mini">${e(x.hook)}</div></div>`).join('')}<div class="job"><b>Blog:</b> ${e(p.blog_brief.title)} — ${e(p.blog_brief.dek)}</div></div></div><pre class="result" style="margin-top:14px">${e(JSON.stringify(p,null,2))}</pre>`;homeStats()}async function disc(){let q=document.getElementById('q').value;let d=await j('/api/research/discover',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic_id:tid,q})});document.getElementById('results').innerHTML=(d.items||[]).map(x=>`<div class="job"><div class="row between"><b>${e(x.title||'Untitled')}</b><span class="badge">signal ${x.signal||0}</span></div><div class="mini">${e(x.url||'')}</div></div>`).join('')||'<div class="muted">No results or connector unavailable.</div>'}async function ingest(){let u=document.getElementById('url').value;if(!tid){document.getElementById('ing').textContent='Select a topic or build a narrative first.';return}let d=await j('/api/research/ingest',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic_id:tid,url:u})});document.getElementById('ing').textContent=JSON.stringify(d);homeStats()}async function homeStats(){let t=await j('/api/topics');let s=0,c=0,n=0;t.topics.forEach(x=>s+=x.source_count||0);let cs=await j('/api/research/claims?topic_id='+(tid||0));c=cs.claims.length;let latest=await j('/api/narrative/latest?topic_id='+(tid||0));n=latest.version||0;document.getElementById('sm').textContent=s;document.getElementById('cm').textContent=c;document.getElementById('nm').textContent=n}homeStats()</script></body></html>'''
class H(BaseHTTPRequestHandler):
 def sendj(self,x,status=200):
  b=json.dumps(x,ensure_ascii=False).encode();self.send_response(status);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
 def do_GET(self):
  p=urlparse(self.path).path;q=parse_qs(urlparse(self.path).query);c=db()
  if p=='/':b=HTML.encode();self.send_response(200);self.send_header('Content-Type','text/html');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b);return
  if p=='/api/health':return self.sendj({'ok':True,'build':'03','narrative_engine':True})
  if p=='/api/topics':return self.sendj({'topics':rows(c,'SELECT t.*,COUNT(s.id) source_count FROM topics t LEFT JOIN sources s ON s.topic_id=t.id GROUP BY t.id ORDER BY score DESC')})
  if p=='/api/channels':return self.sendj({'channels':rows(c,'SELECT * FROM channels')})
  if p=='/api/research/claims':return self.sendj({'claims':rows(c,'SELECT claims.*,sources.title source_title,sources.url FROM claims LEFT JOIN sources ON sources.id=claims.source_id WHERE claims.topic_id=? ORDER BY claims.id DESC',(int(q.get('topic_id',['0'])[0]),))})
  if p=='/api/narrative/latest':
   r=c.execute('SELECT * FROM narrative_packages WHERE topic_id=? ORDER BY version DESC LIMIT 1',(int(q.get('topic_id',['0'])[0]),)).fetchone();return self.sendj({'package':json.loads(r['payload']) if r else None,'version':r['version'] if r else 0})
  return self.sendj({'error':'not found'},404)
 def do_POST(self):
  p=urlparse(self.path).path;b=body(self);c=db()
  if p=='/api/research/discover':
   tid=int(b.get('topic_id',0) or 0);q=str(b.get('q','')).strip();
   if not tid or not q:return self.sendj({'error':'topic_id and q required'},400)
   try:r=discover(q)
   except Exception as e:return self.sendj({'error':str(e)},502)
   c.execute('INSERT INTO discoveries(topic_id,query,payload,created_at) VALUES(?,?,?,?)',(tid,q,json.dumps(r),now()))
   for x in r.get('items',[]):
    if x.get('url'):c.execute('INSERT INTO sources(topic_id,url,title,source_type,trust,notes) VALUES(?,?,?,?,?,?)',(tid,x['url'],x.get('title',''),x.get('kind',x.get('source_type','web')),60,'discovery signal; not evidence'))
   c.commit();return self.sendj(r)
  if p=='/api/research/ingest':
   tid=int(b.get('topic_id',0) or 0);u=str(b.get('url','')).strip()
   if not tid or not u:return self.sendj({'error':'topic_id and url required'},400)
   try:page=fetch_page(u)
   except Exception as e:return self.sendj({'error':str(e)},502)
   sid=c.execute('INSERT INTO sources(topic_id,url,title,source_type,trust,notes) VALUES(?,?,?,?,?,?)',(tid,u,u,'web',70,'fetched; claims require review')).lastrowid
   cs=extract_claim_candidates(page['text'])
   for x in cs:c.execute('INSERT INTO claims(topic_id,claim,source_id,confidence,status,conflict,notes) VALUES(?,?,?,?,?,?,?)',(tid,x,sid,55,'needs_review','unknown','baseline extraction'))
   c.commit();return self.sendj({'ok':True,'source_id':sid,'claims_added':len(cs)})
  if p=='/api/narrative/build':
   topic=str(b.get('topic','')).strip();tid=int(b.get('topic_id',0) or 0)
   if not topic:return self.sendj({'error':'topic required'},400)
   if not tid:
    tid=c.execute('INSERT INTO topics(title,angle,score,demand,competition,originality,researchability,status,created_at) VALUES(?,?,?,?,?,?,?,?,?)',(topic,'Narrative build',0,0,0,0,0,'narrative_ready',now())).lastrowid;c.commit()
   src=rows(c,'SELECT * FROM sources WHERE topic_id=?',(tid,));cl=rows(c,'SELECT * FROM claims WHERE topic_id=?',(tid,));disc=[]
   for r in rows(c,'SELECT payload FROM discoveries WHERE topic_id=? ORDER BY id DESC LIMIT 5',(tid,)):
    try:disc+=json.loads(r['payload']).get('items',[])
    except:pass
   pack=build_narrative(topic,src,cl,disc);v=(c.execute('SELECT MAX(version) v FROM narrative_packages WHERE topic_id=?',(tid,)).fetchone()['v'] or 0)+1;c.execute('INSERT INTO narrative_packages(topic_id,payload,created_at,version) VALUES(?,?,?,?)',(tid,json.dumps(pack,ensure_ascii=False),now(),v));c.commit();return self.sendj({'ok':True,'topic_id':tid,'version':v,'package':pack})
  return self.sendj({'error':'not found'},404)
if __name__=='__main__':db().close();print(f'Creator OS Build 03 running at http://127.0.0.1:{PORT}');ThreadingHTTPServer(('0.0.0.0',PORT),H).serve_forever()
